Stemma.overlapCompat.text:
def overlapCompat {n : ℕ} (s t : PSplit n) : Prop :=
  have W := s.dom ∩ t.dom;
  s.side ∩ t.side ∩ W = ∅ ∨
    s.side ∩ t.other ∩ W = ∅ ∨ s.other ∩ t.side ∩ W = ∅ ∨ s.other ∩ t.other ∩ W = ∅

Stemma.TwoReading.two_reading_nested.text:
theorem two_reading_nested {n : ℕ} {att : Finset (Fin n) → Bool}
  {A e f : Finset (Fin n)} (hfe : f ⊂ e) (hf : f.Nonempty) (hrest : eᶜ.Nonempty) :
  Prop2 {e, f} att A ↔ att e = true ∧ att f = true ∧ (A = e ∨ A = eᶜ)

Stemma.TextIllegible.CondIllegible.text:
def CondIllegible {n : ℕ} {Ω : Type u_1} [MeasurableSpace Ω] (μ : Measure Ω)
  (r : Fin n) (Z : Finset (Fin n) → Ω → ℝ) (I : Fin n → Ω → ℝ) (δ : ℝ) : Prop :=
  ∀ (F : Finset (Finset (Fin n))) (x : Fin n),
    μ.real {ω | CuttingIllegible.zs r Z ω = F ∧ I x ω = 1} ≤
      δ * μ.real {ω | CuttingIllegible.zs r Z ω = F}

Stemma.Splits.maximal.text:
theorem maximal {n : ℕ} {r : Fin n} {T : Finset (Finset (Fin n))}
  (hT : IsBinary r T) {τ : Finset (Fin n)} (hτ : IsSide r τ)
  (hc : ∀ σ ∈ T, Compat τ σ) : τ ∈ T

Stemma.RootedTop.union_weight_nonpos.text:
theorem union_weight_nonpos {n : ℕ} {w : Finset (Fin n) → ℝ}
  {S : Finset (Finset (Fin n))} (hS : IsOptimalR w S) {V : Finset (Fin n)}
  (hV : V ∈ S ∨ V = univ) {D₁ D₂ D₃ : Finset (Fin n)} (h₁ : IsChild S V D₁)
  (h₂ : IsChild S V D₂) (h₃ : IsChild S V D₃) (h12 : D₁ ≠ D₂) (h13 : D₁ ≠ D₃)
  (h23 : D₂ ≠ D₃) : w (D₁ ∪ D₂) ≤ 0

Stemma.RootedTop.two_branched_top.text:
theorem two_branched_top {n : ℕ} {w : Finset (Fin n) → ℝ}
  (hw0 : ∀ (A : Finset (Fin n)), 0 ≤ w A) {S : Finset (Finset (Fin n))}
  (hS : IsOptimalR w S) {V : Finset (Fin n)} (hV : V ∈ S ∨ V = univ)
  {D₁ D₂ D₃ : Finset (Fin n)} (h₁ : IsChild S V D₁) (h₂ : IsChild S V D₂)
  (h₃ : IsChild S V D₃) (h12 : D₁ ≠ D₂) (h13 : D₁ ≠ D₃) (h23 : D₂ ≠ D₃) :
  w (D₁ ∪ D₂) = 0

Stemma.Reduction.decode.text:
noncomputable def decode {V : Type u_1} [Fintype V] [DecidableEq V]
  (H : SimpleGraph V) [DecidableRel H.Adj] (S : Finset (Finset (Fin (N H)))) :
  Finset V := {v | σ H v ∈ S}

Stemma.PolytomyNull.null_bound.text:
theorem null_bound {n : ℕ} {K Cs : Finset (Finset (Fin n))} (hV : Vertex K Cs)
  (hKne : ∀ e ∈ K, e.Nonempty) (hK : Laminar K) {ci cj : Finset (Fin n)}
  (hi : ci ∈ Cs) (hj : cj ∈ Cs) (hij : ci ≠ cj) {π : Finset (Fin n) → ℝ} {α : ℝ}
  (hπ0 : ∀ (e : Finset (Fin n)), 0 ≤ π e) (hπ1 : ∀ (e : Finset (Fin n)), π e ≤ 1)
  (hα0 : 0 ≤ α) (hα1 : α ≤ 1) (hs1 : ∑ g ∈ K, π g ≤ 1) :
  |ex K π α (PR (ci ∪ cj)) - lead Cs K ci cj α (q K π α)| ≤ 7 * (∑ g ∈ K, π g) ^ 3

Stemma.PolytomyNull.nonorig.text:
noncomputable def nonorig {n : ℕ} (M : Finset (Finset (Fin n)))
  (att : Finset (Fin n) → Bool) : Finset (Fin n) :=
  {x | Mechanisms.read M att x ≠ Rd.orig}

Stemma.NPHard.WeightedSplits.text:
def WeightedSplits : Set WSplitInstance :=
  {x |
    WFW x ∧
      ∃ T,
        (∀ c ∈ T, c ∈ x.cands) ∧
          x.k ≤ ∑ c ∈ T, c.2 ∧ ∀ c ∈ T, ∀ c' ∈ T, c ≠ c' → OK x.univ c.1 c'.1}

Stemma.NPHard.OK.text:
def OK (U A B : List ℕ) : Prop :=
  A.toFinset ≠ B.toFinset ∧
    A.toFinset ≠ U.toFinset \ B.toFinset ∧ CompatU U.toFinset A.toFinset B.toFinset

Stemma.Mechanisms.cls.text:
noncomputable def cls {n : ℕ} (M : Finset (Finset (Fin n)))
  (att : Finset (Fin n) → Bool) (v : Rd n) : Finset (Fin n) :=
  {x | read M att x = v}

Stemma.FragmentaryUnits.pairwise_YN.text:
lemma pairwise_YN {n : ℕ} {Ω : Type u_1} [MeasurableSpace Ω] {μ : Measure Ω}
  [IsProbabilityMeasure μ] {r : Fin n} {Z : ℕ → Finset (Fin n) → Ω → ℝ}
  {I : ℕ → Fin n → Ω → ℝ} (hV : iIndepFun (VN Z I) μ) :
  Pairwise fun i j ↦ (fun ω σ ↦ YN r Z I σ i ω) ⟂ᵢ[μ] fun ω σ ↦ YN r Z I σ j ω

Stemma.FragmentaryUnits.integral_YN.text:
lemma integral_YN {n : ℕ} {Ω : Type u_1} [MeasurableSpace Ω] {μ : Measure Ω}
  [IsProbabilityMeasure μ] {r : Fin n} {Z : ℕ → Finset (Fin n) → Ω → ℝ}
  {I : ℕ → Fin n → Ω → ℝ} (hZ : ∀ (u : ℕ) (σ : Finset (Fin n)), Measurable (Z u σ))
  (hIm : ∀ (u : ℕ) (x : Fin n), Measurable (I u x)) (τ : Finset (Fin n)) :
  ∫ (x : Ω), YN r Z I τ 0 x ∂μ = mtN μ r Z I τ

Stemma.FragmentaryUnits.integral_Y.text:
lemma integral_Y {n : ℕ} {Ω : Type u_1} [MeasurableSpace Ω] {μ : Measure Ω}
  [IsProbabilityMeasure μ] {L : ℕ} (hL : 0 < L) {r : Fin n}
  {Z : Fin L → Finset (Fin n) → Ω → ℝ} {I : Fin L → Fin n → Ω → ℝ}
  (hZ : ∀ (u : Fin L) (σ : Finset (Fin n)), Measurable (Z u σ))
  (hIm : ∀ (u : Fin L) (x : Fin n), Measurable (I u x))
  (hident : ∀ (u : Fin L), IdentDistrib (V Z I u) (V Z I ⟨0, hL⟩) μ μ)
  (τ : Finset (Fin n)) (u : Fin L) : ∫ (x : Ω), Y r Z I τ u x ∂μ = mt hL μ r Z I τ

Stemma.FragmentaryUnits.ident_YN.text:
lemma ident_YN {n : ℕ} {Ω : Type u_1} [MeasurableSpace Ω] {μ : Measure Ω}
  [IsProbabilityMeasure μ] {r : Fin n} {Z : ℕ → Finset (Fin n) → Ω → ℝ}
  {I : ℕ → Fin n → Ω → ℝ}
  (hident : ∀ (u : ℕ), IdentDistrib (VN Z I u) (VN Z I 0) μ μ) (u : ℕ) :
  IdentDistrib (fun ω σ ↦ YN r Z I σ u ω) (fun ω σ ↦ YN r Z I σ 0 ω) μ μ

Stemma.FragmentaryUnits.iIndep_Y.text:
lemma iIndep_Y {n : ℕ} {Ω : Type u_1} [MeasurableSpace Ω] {μ : Measure Ω}
  [IsProbabilityMeasure μ] {L : ℕ} {r : Fin n} {Z : Fin L → Finset (Fin n) → Ω → ℝ}
  {I : Fin L → Fin n → Ω → ℝ} (hV : iIndepFun (V Z I) μ) (τ : Finset (Fin n)) :
  iIndepFun (Y r Z I τ) μ

Stemma.FragmentaryUnits.VN.text:
def VN {n : ℕ} {Ω : Type u_1} (Z : ℕ → Finset (Fin n) → Ω → ℝ)
  (I : ℕ → Fin n → Ω → ℝ) (u : ℕ) (ω : Ω) : UnitData n :=
  (fun σ ↦ Z u σ ω, fun x ↦ I u x ω)

Stemma.FragmentaryUnits.V.text:
def V {n : ℕ} {Ω : Type u_1} {L : ℕ} (Z : Fin L → Finset (Fin n) → Ω → ℝ)
  (I : Fin L → Fin n → Ω → ℝ) (u : Fin L) (ω : Ω) : UnitData n :=
  (fun σ ↦ Z u σ ω, fun x ↦ I u x ω)

Stemma.Fragmentary.mR.text:
noncomputable def mR {n : ℕ} {Ω : Type u_1} [MeasurableSpace Ω] (μ : Measure Ω)
  (r : Fin n) (Z : Finset (Fin n) → Ω → ℝ) (I : Fin n → Ω → ℝ)
  (τ : Finset (Fin n)) : ℝ := μ.real {ω | ProposesRestr r Z I τ ω}

Stemma.Fragmentary.ProposesRestr.text:
def ProposesRestr {n : ℕ} {Ω : Type u_1} (r : Fin n) (Z : Finset (Fin n) → Ω → ℝ)
  (I : Fin n → Ω → ℝ) (τ : Finset (Fin n)) (ω : Ω) : Prop :=
  NontrivOn (legible I ω) τ ∧ ∃ σ ∈ sides r, Z σ ω = 1 ∧ SameRestr (legible I ω) σ τ

Stemma.Five.Perfect.text:
def Perfect {V : Type u_1} (G : SimpleGraph V) : Prop :=
  ∀ (s : Set V),
    ↑(SimpleGraph.induce s G).cliqueNum = (SimpleGraph.induce s G).chromaticNumber

Stemma.CuttingRemark.displayed_without_p.text:
theorem displayed_without_proposal :
  have σ := {0, 1};
  have σ' := {0, 1, 2};
  have O := {0, 1, 3, 4};
  IsSide 4 σ ∧ IsSide 4 σ' ∧ σ ≠ σ' ∧ NontrivOn O σ' ∧ Displays {σ} (canon O σ')

Stemma.CuttingRemark.Full.text:
def Full {n : ℕ} {Ω : Type u_1} (Z : ℕ → Finset (Fin n) → Ω → ℝ)
  (I : ℕ → Fin n → Ω → ℝ) (σ : Finset (Fin n)) (u : ℕ) : Set Ω :=
  {ω | Z u σ ω = 1 ∧ ∀ (x : Fin n), I u x ω = 0}

Stemma.CuttingPlanes.relaxation.text:
theorem relaxation {n : ℕ} {C : Finset (PSplit n)}
  {cuts : Finset (Finset (PSplit n))} (hv : ValidCuts cuts) {F : Finset (PSplit n)}
  (hFC : F ⊆ C) (hF : JointlyCompletable F) : Feasible C cuts F

Stemma.CuttingPlanes.cutting_correct.text:
theorem cutting_correct {n : ℕ} {C : Finset (PSplit n)} {c : PSplit n → ℝ}
  {cuts : Finset (Finset (PSplit n))} (hv : ValidCuts cuts) {S : Finset (PSplit n)}
  (hS : IsMasterOpt C c cuts S) (hSc : JointlyCompletable S) :
  S ⊆ C ∧
    JointlyCompletable S ∧ ∀ F ⊆ C, JointlyCompletable F → weight c F ≤ weight c S

Stemma.CuttingIllegible.zs.text:
noncomputable def zs {n : ℕ} {Ω : Type u_1} (r : Fin n)
  (Z : Finset (Fin n) → Ω → ℝ) (ω : Ω) : Finset (Finset (Fin n)) :=
  {σ ∈ sides r | Z σ ω = 1}

Stemma.CuttingIllegible.mu2.text:
noncomputable def mu2 {n : ℕ} {Ω : Type u_1} [MeasurableSpace Ω] (μ : Measure Ω)
  (r : Fin n) (Z : Finset (Fin n) → Ω → ℝ) : ℝ :=
  1 / 2 * ∑ p ∈ (sides r).offDiag, μ.real {ω | Z p.1 ω = 1 ∧ Z p.2 ω = 1}

Stemma.CuttingIllegible.canon.text:
noncomputable def canon {n : ℕ} (O A : Finset (Fin n)) : PSplit n :=
  if h : O.Nonempty then
    if O.min' h ∈ A then { dom := O, side := O \ A, sub := ⋯ }
    else { dom := O, side := A ∩ O, sub := ⋯ }
  else { dom := O, side := ∅, sub := ⋯ }

Stemma.CuttingIllegible.M_upper.text:
theorem M_upper {n : ℕ} {Ω : Type u_1} [MeasurableSpace Ω] {μ : Measure Ω}
  [IsProbabilityMeasure μ] {r : Fin n} {Z : Finset (Fin n) → Ω → ℝ}
  {I : Fin n → Ω → ℝ} {δ : ℝ} (hZ : ∀ (σ : Finset (Fin n)), Measurable (Z σ))
  (hIm : ∀ (x : Fin n), Measurable (I x))
  (hI01 : ∀ (x : Fin n) (ω : Ω), I x ω = 0 ∨ I x ω = 1)
  (hindZI : (fun ω σ ↦ Z σ ω) ⟂ᵢ[μ] fun ω x ↦ I x ω) (hindI : iIndepFun I μ)
  (hδ : ∀ (x : Fin n), μ.real {ω | I x ω = 1} ≤ δ) {T' : Finset (Finset (Fin n))}
  (hT' : T' ⊆ sides r) :
  ∫ (ω : Ω), ↑(count T' (zs r Z ω) (legible I ω)) ∂μ ≤
    ∑ σ ∈ T', mC μ Z σ + 2 * δ * ↑(#T') * mu1 μ r Z

Stemma.CuttingIllegible.M_lower.text:
theorem M_lower {n : ℕ} {Ω : Type u_1} [MeasurableSpace Ω] {μ : Measure Ω}
  [IsProbabilityMeasure μ] {r : Fin n} {Z : Finset (Fin n) → Ω → ℝ}
  {I : Fin n → Ω → ℝ} {δ : ℝ} (hZ : ∀ (σ : Finset (Fin n)), Measurable (Z σ))
  (hIm : ∀ (x : Fin n), Measurable (I x))
  (hI01 : ∀ (x : Fin n) (ω : Ω), I x ω = 0 ∨ I x ω = 1)
  (hindZI : (fun ω σ ↦ Z σ ω) ⟂ᵢ[μ] fun ω x ↦ I x ω) (hindI : iIndepFun I μ)
  (hδ : ∀ (x : Fin n), μ.real {ω | I x ω = 1} ≤ δ) {T : Finset (Finset (Fin n))}
  (hT : T ⊆ sides r) :
  (1 - 4 * δ) * ∑ σ ∈ T, mC μ Z σ - 2 * δ * mu2 μ r Z ≤
    ∫ (ω : Ω), ↑(count T (zs r Z ω) (legible I ω)) ∂μ

Stemma.CuttingIllegible.M_eq.text:
lemma M_eq {n : ℕ} {Ω : Type u_1} [MeasurableSpace Ω] {μ : Measure Ω}
  [IsProbabilityMeasure μ] {r : Fin n} {Z : Finset (Fin n) → Ω → ℝ}
  {I : Fin n → Ω → ℝ} {P : ℕ → Ω → Finset (PSplit n)} (hP0 : P 0 = unitProps r Z I)
  (T : Finset (Finset (Fin n))) :
  M μ P T = ∫ (ω : Ω), ↑(count T (zs r Z ω) (legible I ω)) ∂μ

Stemma.CuttingDimFree.display_prob_le.text:
theorem display_prob_le {n : ℕ} {Ω : Type u_1} [MeasurableSpace Ω] {μ : Measure Ω}
  [IsProbabilityMeasure μ] {r : Fin n} {Z : Finset (Fin n) → Ω → ℝ}
  {I : Fin n → Ω → ℝ} {δ : ℝ} (hZ : ∀ (σ : Finset (Fin n)), Measurable (Z σ))
  (hI01 : ∀ (x : Fin n) (ω : Ω), I x ω = 0 ∨ I x ω = 1)
  (hindZI : (fun ω σ ↦ Z σ ω) ⟂ᵢ[μ] fun ω x ↦ I x ω) (hindI : iIndepFun I μ)
  (hδ : ∀ (x : Fin n), μ.real {ω | I x ω = 1} ≤ δ) {T' : Finset (Finset (Fin n))}
  (hT' : IsBinary r T') {σ : Finset (Fin n)} (hσ : σ ∈ sides r) (hσT : σ ∉ T') :
  μ.real (DisplayEvent Z I T' σ) ≤ 2 * max δ (2 * δ ^ 2) * mC μ Z σ

Stemma.CuttingDimFree.DisplayEvent.text:
def DisplayEvent {n : ℕ} {Ω : Type u_1} (Z : Finset (Fin n) → Ω → ℝ)
  (I : Fin n → Ω → ℝ) (T' : Finset (Finset (Fin n))) (σ : Finset (Fin n)) : Set Ω :=
  {ω |
    Z σ ω = 1 ∧ NontrivOn (legible I ω) σ ∧ ∃ τ ∈ T', SameRestr (legible I ω) τ σ}

Stemma.Cutting.completable_of_displayed.text:
theorem completable_of_displayed {n : ℕ} {r : Fin n} {T : Finset (Finset (Fin n))}
  (hT : IsBinary r T) (P : Finset (PSplit n)) (hd : ∀ s ∈ P, Displays T s) :
  JointlyCompletable P

Stemma.Crossing.side.text:
noncomputable def side {n : ℕ} {W : Type u_1} (T : SimpleGraph W) (φ : Fin n → W)
  (e : Sym2 W) (w : W) : Finset (Fin n) :=
  {y | (T.deleteEdges {e}).Reachable w (φ y)}

Stemma.Crossing.mem_path_iff.text:
theorem mem_path_iff {W : Type u_1} {T : SimpleGraph W} (hT : T.IsTree) {u v : W}
  (p : T.Walk u v) (hp : p.IsPath) (e : Sym2 W) :
  e ∈ p.edges ↔ ¬(T.deleteEdges {e}).Reachable u v

Stemma.Crossing.crossing_path.text:
theorem crossing_path {n : ℕ} {W : Type u_1} {T : SimpleGraph W} {φ : Fin n → W}
  (hT : T.IsTree) {A : Finset (Fin n)} {e f : Sym2 W}
  (he : InSpan T φ A e ∧ InSpan T φ Aᶜ e) (hf : InSpan T φ A f ∧ InSpan T φ Aᶜ f)
  {u v : W} (hu : u ∈ e) (hv : v ∈ f) (p : T.Walk u v) (hp : p.IsPath) {g : Sym2 W}
  (hg : g ∈ p.edges) : InSpan T φ A g ∧ InSpan T φ Aᶜ g

Stemma.Crossing.crossing_nonempty.text:
theorem crossing_nonempty {n : ℕ} {W : Type u_1} {T : SimpleGraph W} {φ : Fin n → W}
  [Fintype W] (hn : 3 ≤ n) (r : Fin n) (hB : IsBinaryTree T φ) {A : Finset (Fin n)}
  (hA : IsSide r A) (hnot : A ∉ nsplits T φ r) :
  ∃ e ∈ T.edgeSet, InSpan T φ A e ∧ InSpan T φ Aᶜ e

Stemma.Crossing.crossing_internal.text:
theorem crossing_internal {n : ℕ} {W : Type u_1} {T : SimpleGraph W} {φ : Fin n → W}
  {e : Sym2 W} {A : Finset (Fin n)} {w : W} (h : ¬Compat A (side T φ e w)) :
  2 ≤ #(side T φ e w) ∧ 2 ≤ #(side T φ e w)ᶜ

Stemma.Crossing.crossing_iff.text:
theorem crossing_iff {n : ℕ} {W : Type u_1} {T : SimpleGraph W} {φ : Fin n → W}
  (hT : T.IsTree) {e : Sym2 W} (he : e ∈ T.edgeSet) (A : Finset (Fin n)) (w : W) :
  ¬Compat A (side T φ e w) ↔ InSpan T φ A e ∧ InSpan T φ Aᶜ e

Stemma.Crossing.InSpan.text:
def InSpan {n : ℕ} {W : Type u_1} (T : SimpleGraph W) (φ : Fin n → W)
  (A : Finset (Fin n)) (e : Sym2 W) : Prop :=
  ∃ a ∈ A, ∃ a' ∈ A, ∃ p, p.IsPath ∧ e ∈ p.edges

Stemma.ClopperPearson.supp.text:
noncomputable def supp {n : ℕ} {Ω : Type u_1} {L : ℕ}
  (Y : Finset (Fin n) → Fin L → Ω → ℝ) (s : Finset (Fin n)) (ω : Ω) : ℕ :=
  #{u | Y s u ω = 1}

Stemma.ClopperPearson.cpUpper_coverage.text:
theorem cpUpper_coverage {Ω : Type u_1} [MeasurableSpace Ω] {μ : Measure Ω}
  [IsProbabilityMeasure μ] {L : ℕ} {X : Ω → ℕ} (hX : Measurable X) {p : ℝ}
  (hbin :
    ∀ (k : ℕ), μ.real {ω | X ω = k} = ↑(L.choose k) * p ^ k * (1 - p) ^ (L - k))
  (hp : p ∈ Set.Icc 0 1) {β : ℝ} (hβ0 : 0 ≤ β) (hβ : β ≤ 1) :
  μ.real {ω | cpUpper L β (X ω) < p} ≤ β

Stemma.ClopperPearson.cpLower_coverage.text:
theorem cpLower_coverage {Ω : Type u_1} [MeasurableSpace Ω] {μ : Measure Ω}
  [IsProbabilityMeasure μ] {L : ℕ} {X : Ω → ℕ} (hX : Measurable X) {p : ℝ}
  (hbin :
    ∀ (k : ℕ), μ.real {ω | X ω = k} = ↑(L.choose k) * p ^ k * (1 - p) ^ (L - k))
  (hp : p ∈ Set.Icc 0 1) {β : ℝ} (hβ0 : 0 ≤ β) (hβ : β ≤ 1) :
  μ.real {ω | p < cpLower L β (X ω)} ≤ β

Stemma.Chernoff.falseOcc.text:
noncomputable def falseOcc {n : ℕ} (r : Fin n) (T : Finset (Finset (Fin n)))
  (m : Finset (Fin n) → ℝ) : Finset (Finset (Fin n)) :=
  {τ | Splits.IsSide r τ ∧ τ ∉ T ∧ 0 < m τ}

Stemma.Chernoff.conflictPairs.text:
noncomputable def conflictPairs {n : ℕ} (r : Fin n) (T : Finset (Finset (Fin n)))
  (m : Finset (Fin n) → ℝ) : Finset (Finset (Fin n) × Finset (Fin n)) :=
  {p ∈ {τ | Splits.IsSide r τ ∧ τ ∉ T ∧ 0 < m τ} ×ˢ T | ¬Compat p.1 p.2}

Stemma.Buneman.nontrivial_splits_of_tree.text:
theorem nontrivial_splits_of_tree {n : ℕ} {r : Fin n} {S : Finset (Finset (Fin n))}
  (hS : ∀ A ∈ S, IsSide r A) {m : ℕ} {T : SimpleGraph (Fin m)} {φ : Fin n → Fin m}
  (h : splitSides T φ = fam S) (B : Finset (Fin n)) (hB : IsSide r B) :
  ↑B ∈ splitSides T φ ↔ B ∈ S

Stemma.Buneman.buneman_unique.text:
theorem buneman_unique {n m m' : ℕ} {T : SimpleGraph (Fin m)}
  {T' : SimpleGraph (Fin m')} {φ : Fin n → Fin m} {φ' : Fin n → Fin m'}
  (hT : IsXTree T φ) (hT' : IsXTree T' φ') (h : splitSides T φ = splitSides T' φ')
  (hn : 0 < n) : ∃ f, ∀ (x : Fin n), f (φ x) = φ' x

Stemma.Buneman.buneman.text:
theorem buneman {n : ℕ} (hn : 2 ≤ n) (r : Fin n) {S : Finset (Finset (Fin n))}
  (hS : ∀ A ∈ S, IsSide r A) :
  IsSystem r S ↔ ∃ m T φ, IsXTree T φ ∧ splitSides T φ = fam S

Stemma.BinaryTree.nsplits.text:
noncomputable def nsplits {n : ℕ} {W : Type u_1} (T : SimpleGraph W)
  (φ : Fin n → W) (r : Fin n) : Finset (Finset (Fin n)) :=
  {B | IsSide r B ∧ ↑B ∈ splitSides T φ}

Stemma.BinaryTree.isBinaryTree_of_fam.text:
theorem isBinaryTree_of_fam {n : ℕ} {W : Type u_1} [Fintype W] {T : SimpleGraph W}
  {φ : Fin n → W} (hn : 3 ≤ n) {r : Fin n} {S : Finset (Finset (Fin n))}
  (hS : IsBinary r S) (hX : IsXTree T φ) (hfam : splitSides T φ = fam S) :
  IsBinaryTree T φ

Stemma.BinaryTree.binary_tree_splits.text:
theorem binary_tree_splits {n : ℕ} {W : Type u_1} [Fintype W] {T : SimpleGraph W}
  {φ : Fin n → W} (hn : 3 ≤ n) (r : Fin n) (hB : IsBinaryTree T φ) :
  IsBinary r (nsplits T φ r) ∧ splitSides T φ = fam (nsplits T φ r)

Stemma.Attraction.sum_wt_A.text:
lemma sum_wt_A {n : ℕ} {K : Finset (Finset (Fin n))} {π : Finset (Fin n) → ℝ}
  {α : ℝ} (M : Finset (Finset (Fin n))) :
  ∑ A ∈ M.powerset, wt K π α M A = (∏ e ∈ M, π e) * ∏ g ∈ K \ M, (1 - π g)

Stemma.Attraction.P3_le.text:
theorem P3_le {n : ℕ} {K : Finset (Finset (Fin n))} {π : Finset (Fin n) → ℝ} {α : ℝ}
  (hπ0 : ∀ (e : Finset (Fin n)), 0 ≤ π e) (hπ1 : ∀ (e : Finset (Fin n)), π e ≤ 1) :
  P3 K π α ≤ esymm K π 3 ∧ esymm K π 3 ≤ (∑ e ∈ K, π e) ^ 3 / 6

Phylogenetics.SplitsEquivalence.exists_x.text:
theorem exists_xTree_iff {X : Type u_1} [Finite X] [Nonempty X] {F : Set (Set X)}
  (hF : IsSplitSystem F) :
  PairwiseCompatible F ↔ ∃ n T φ, IsXTree T φ ∧ splitSides T φ = F
